def count_nums(arr):
    def sum_digits(n):
        s, n = 0, abs(n)
        while n:
            s += n % 10
            n //= 10
        return -s if n < 0 else s
    return sum(1 for x in arr if x and (x > 0 or sum_digits(x) > 0))
