def count_nums(arr):
    def sum_digits(n):
        s = 0
        n = str(n)
        for i, ch in enumerate(n):
            if i == 0 and ch == '-':
                continue
            if i == 1 and n[0] == '-':
                s -= int(ch)
            else:
                s += int(ch)
        return s
    return sum(1 for x in arr if sum_digits(x) > 0)
```

