def count_nums(arr):
    def signed_digit_sum(n):
        if n == 0:
            return 0
        if n < 0:
            n = -n
            total = -(n % 10)
            n //= 10
        else:
            total = 0
        while n:
            total += n % 10
            n //= 10
        return total

    return sum(1 for x in arr if signed_digit_sum(x) > 0)
```

